REVISED=''
import base64,fcntl,hashlib,json,os,subprocess,sys
from pathlib import Path
boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip();assert boot=='a69299ef-17d0-446f-a0df-56c0a08cd2fb'
root=Path('/home/root/aura-native-live-20261024/ops/be72669aa53de735');sys.path.insert(0,str(root))
from boot_ops import Ops
from policy import benchmark_safe
ops=Ops(root);ops.verify();source=Path(sys._getframe().f_code.co_filename).resolve()
tag=hashlib.sha256(source.read_bytes()).hexdigest()[:16];folder=root/('benchmark-retry-'+tag)
if sys.argv[1:]!=['--worker']:
 assert not sys.argv[1:]
 state=ops.state();assert state['phase']=='BENCHMARK_SAFE_FAILURE' and state['benchmark_cleanup_confirmed']
 for unit in ['aura-camera-ui.service','aura-avatar-ui.service']:assert ops.props(unit)['MainPID']=='0'
 with open('/run/aura-person-dpu.lock','a+') as lock:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 folder.mkdir(mode=0o700);(folder/'previous-failed-report.json').write_text(json.dumps(state['benchmark_report'],indent=2)+'\n')
 (folder/'equivalence_benchmark.py').write_bytes(base64.b64decode(REVISED))
 p=subprocess.run(['systemd-run','--quiet','--unit=aura-native-equivalence-retry-'+tag,
 '--property=Type=oneshot','--property=RuntimeMaxSec=infinity','--property=TimeoutStopSec=infinity',
 '--property=SendSIGKILL=no','--property=KillMode=process','--property=Restart=no',
 '/usr/bin/python3','-B',str(source),'--worker'],capture_output=True,text=True,timeout=8)
 assert p.returncode==0,p.stderr
 print(json.dumps({'started':True,'scope':'revised reference-before-primary comparison; same30ms/5ms/100ms, known prior cleanup',
 'unit':'aura-native-equivalence-retry-'+tag+'.service','folder':str(folder)}))
 raise SystemExit(0)
lock=(root/'operation.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
assert ops.state()['phase']=='BENCHMARK_SAFE_FAILURE'
ops.phase('MAINTENANCE',maintenance_started=True,benchmark_revision=tag)
meta=ops.meta
args=['/usr/bin/python3','-B',str(root/'build_plan.py'),'--legacy-root',meta['legacy_root']+'/aura',
 '--candidate-root',meta['candidate_root']+'/aura','--bridge',meta['native_library'],
 '--production-snapshot',meta['prefix_path'],'--expected-boot-id',boot,
 '--yolo-owner-config',str(root/'yolo.json'),'--optional-models',str(root/'models.json'),
 '--new-output-directory',str(folder/'plan')]
ops.command(args,timeout=25)
result=folder/'result'
with (folder/'benchmark.log').open('xb') as log:
 p=subprocess.Popen(['/usr/bin/python3','-B',str(folder/'equivalence_benchmark.py'),
 '--plan',str(folder/'plan/plan.json'),'--output-directory',str(result),'--execute-maintenance'],stdout=log,stderr=subprocess.STDOUT)
 ops.phase('MAINTENANCE',benchmark_pid=p.pid,benchmark_result=str(result/'result.json'))
 code=p.wait()
report=json.loads((result/'result.json').read_text()) if (result/'result.json').exists() else None
checkpoint=json.loads((result/'checkpoint.json').read_text()) if (result/'checkpoint.json').exists() else None
safe=benchmark_safe(report,checkpoint,code,False)
state=ops.phase('QUALIFIED' if safe and report and report.get('passed') else 'BENCHMARK_SAFE_FAILURE' if safe else 'UNSAFE_HOLD',
 benchmark_exit=code,benchmark_cleanup_confirmed=safe,benchmark_report=report)
print(json.dumps({'phase':state['phase'],'report':report}))
